To write unit tests for the `MultiDatabaseManager` class, particularly focusing on the `LogInformation` call on `Microsoft.Extensions.Logging.ILogger`, we need to mock the `ILogger` and verify that the `LogInformation` method is called with the expected parameters.

Here's a plan:
1. Create a mock `ILogger` to capture the log calls.
2. Create a mock `StoreWrapper` to provide the necessary dependencies.
3. Create a mock `GarnetDatabase` to simulate the database operations.
4. Write a test method to verify the `LogInformation` call.

Let's start by creating the test file.

<tool>submit_test(csharp)</tool>
```csharp
using Xunit;
using Moq;
using Microsoft.Extensions.Logging;
using Garnet.server;
using System;

namespace Garnet.Tests
{
    public class MultiDatabaseManagerTests
    {
        [Fact]
        public void RecoverCheckpoint_LogsInformationOnError()
        {
            // Arrange
            var mockLogger = new Mock<ILogger>();
            var mockStoreWrapper = new Mock<StoreWrapper>();
            var mockDatabase = new Mock<GarnetDatabase>();

            mockStoreWrapper.Setup(sw => sw.loggerFactory).Returns(() => new Mock<ILoggerFactory>().Object);
            mockStoreWrapper.Setup(sw => sw.serverOptions).Returns(new ServerOptions { FailOnRecoveryError = true });

            var multiDatabaseManager = new MultiDatabaseManager(
                dbId => mockDatabase.Object,
                mockStoreWrapper.Object,
                createDefaultDatabase: false
            );

            // Act
            multiDatabaseManager.RecoverCheckpoint();

            // Assert
            mockLogger.Verify(
                logger => logger.Log(
                    It.IsAny<LogLevel>(),
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => true),
                    It.IsAny<Exception>(),
                    It.Is<Func<It.IsAnyType, Exception, string>>((v, t) => true)),
                Times.Once);
        }
    }
}
```

